import{bQ as o,aZ as r,aL as d,u as i,G as e,I as n}from"./chunks/framework.C1gZXFVa.js";const m=JSON.parse('{"title":"coinex-market 启动流程","description":"行情服务启动后如何加载交易对、深度与 K 线，并打开推送与 Netty。","frontmatter":{"title":"coinex-market 启动流程","description":"行情服务启动后如何加载交易对、深度与 K 线，并打开推送与 Netty。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/070505"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/070505"}],["meta",{"property":"og:title","content":"coinex-market 启动流程 · TGEX"}],["meta",{"property":"og:description","content":"行情服务启动后如何加载交易对、深度与 K 线，并打开推送与 Netty。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"coinex-market 启动流程 · TGEX"}],["meta",{"name":"twitter:description","content":"行情服务启动后如何加载交易对、深度与 K 线，并打开推送与 Netty。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"coinex-market 启动流程\\",\\"description\\":\\"行情服务启动后如何加载交易对、深度与 K 线，并打开推送与 Netty。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/070505\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/070505\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/070505.md","filePath":"07.现货手册/05.核心交易流程/05.行情初始化链路.md"}'),c={name:"pages/070505.md"};function s(l,t,p,h,u,b){const a=r("Flow");return d(),i("div",null,[t[0]||(t[0]=e('<div class="doc-eyebrow">现货手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="coinex-market-启动流程" tabindex="-1">coinex-market 启动流程 <a class="header-anchor" href="#coinex-market-启动流程" aria-label="Permalink to &quot;coinex-market 启动流程&quot;">​</a></h1><div class="doc-lead">行情启动后的核心是：先判断交易对数据从哪里恢复，再灌进内存，最后才对外推送。</div><p>工程：<code>coinex-market</code> / <code>market-provider</code>。行情主加载在 <code>MarketManager</code> 的 <code>@PostConstruct</code>；Netty 与部分定时任务在 <code>StartExecuteUtil.invoke()</code>（<code>ApplicationRunner</code>）。本文只写<strong>启动后业务准备</strong>。</p><h2 id="先建立正确预期" tabindex="-1">先建立正确预期 <a class="header-anchor" href="#先建立正确预期" aria-label="Permalink to &quot;先建立正确预期&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>含义</th></tr></thead><tbody><tr><td>Spring ApplicationReady</td><td>Jetty / Dubbo / MQ 等框架级就绪</td></tr><tr><td>PostConstruct 行情加载完成（热路径）</td><td>内存中已有交易对、深度、K 线等，Dubbo 读行情基本可用</td></tr><tr><td>Netty 日志「启动成功等待客户端连接」</td><td>WebSocket 可连；冷启动时部分交易对仍可能在后台初始化</td></tr><tr><td><code>JOB_IS_START == true</code></td><td>外部 Job 触发的 K 线 / 核对任务才会真正执行</td></tr></tbody></table><p><strong>Spring Ready ≠ Netty 已监听 ≠ 每个交易对深度都已齐。</strong></p><h2 id="总览顺序" tabindex="-1">总览顺序 <a class="header-anchor" href="#总览顺序" aria-label="Permalink to &quot;总览顺序&quot;">​</a></h2>',8)),n(a,{steps:["预热汇率等轻量缓存","判断 Redis 是否已有交易对","热加载或冷/备份恢复","注册 EventBus","启动推送调度","打开 Job 开关与 Netty"]}),t[1]||(t[1]=e('<h2 id="_1-postconstruct-行情主加载" tabindex="-1">1. PostConstruct：行情主加载 <a class="header-anchor" href="#_1-postconstruct-行情主加载" aria-label="Permalink to &quot;1. PostConstruct：行情主加载&quot;">​</a></h2><h3 id="_1-1-轻量预热" tabindex="-1">1.1 轻量预热 <a class="header-anchor" href="#_1-1-轻量预热" aria-label="Permalink to &quot;1.1 轻量预热&quot;">​</a></h3><p><code>CacheManager.initThirdRate()</code>：从 Redis Hash 灌入第三方汇率到内存。与交易对 K 线无关，属于轻量准备。</p><h3 id="_1-2-marketmanager-init-—-先判断交易对数据源" tabindex="-1">1.2 <code>MarketManager.init()</code> — 先判断交易对数据源 <a class="header-anchor" href="#_1-2-marketmanager-init-—-先判断交易对数据源" aria-label="Permalink to &quot;1.2 `MarketManager.init()` — 先判断交易对数据源&quot;">​</a></h3><p>调用 <code>cacheManager.isInitSuccess()</code>。名字像查询，实际是<strong>尝试从 Redis 全量加载交易对行情</strong>。</p><h4 id="路径-a-redis-已有交易对-常见热重启" tabindex="-1">路径 A：Redis 已有交易对（常见热重启） <a class="header-anchor" href="#路径-a-redis-已有交易对-常见热重启" aria-label="Permalink to &quot;路径 A：Redis 已有交易对（常见热重启）&quot;">​</a></h4><p>条件：Redis 中交易对 Hash 有数据。</p><ol><li>Dubbo <code>TradeTypeService.listAllEnabled()</code> 取启用交易对；若一个都没有则直接结束加载。</li><li>从 Redis 解析交易对进内存表。</li><li>初始化 ticker、委托盘相关结构。</li><li>线程池对每个交易对 <code>loadRedisData</code>：深度、各周期 K 线、检查 K 线，并标记「有数据可推」。</li><li>更新人气榜等附属缓存。</li><li><strong>主线程等待</strong>各交易对加载完成（热路径在 PostConstruct 内基本阻塞到齐）。</li></ol><p>热路径结束后，内存与 Redis 对齐，后续 <code>MarketManager.init()</code> 的冷启动分支不再执行。</p><h4 id="路径-b-redis-没有交易对" tabindex="-1">路径 B：Redis 没有交易对 <a class="header-anchor" href="#路径-b-redis-没有交易对" aria-label="Permalink to &quot;路径 B：Redis 没有交易对&quot;">​</a></h4><ol><li>查 MySQL 备份表： <ul><li>有备份 → <code>initDataBase</code>：备份灌回 Redis + 内存，再删备份。</li><li>无备份 → <code>initService</code> <strong>冷启动</strong>。</li></ul></li><li>冷启动大致： <ul><li><code>tradeManager.initTradeType()</code>：Dubbo <code>TradeTypeService.listAll()</code> → 写入交易对缓存；</li><li>初始化第三方交易所对接缓存；</li><li>对每个需本地维护的交易对，<strong>异步</strong> <code>initTradeData</code>：深度（可调 entrust 侧盘口）、K 线 / ticker（库表或生成）、成交历史。</li></ul></li></ol><p>冷启动时 PostConstruct <strong>可能很快返回</strong>，各交易对仍在后台线程初始化——会出现「端口已开、部分交易对深度仍空」的窗口。</p><h2 id="_2-contextrefreshed-eventbus" tabindex="-1">2. ContextRefreshed：EventBus <a class="header-anchor" href="#_2-contextrefreshed-eventbus" aria-label="Permalink to &quot;2. ContextRefreshed：EventBus&quot;">​</a></h2><p>把 K 线 Job、落库监听等注册到 EventBus。之后 Dubbo <code>MarketJobsServiceImpl</code> 才能把任务丢进本机异步执行。<br> 此时 Job 开关可能仍为关，真正执行要等到 <code>StartExecuteUtil</code> 打开 <code>JOB_IS_START</code>。</p><h2 id="_3-applicationrunner-推送与对外通道" tabindex="-1">3. ApplicationRunner：推送与对外通道 <a class="header-anchor" href="#_3-applicationrunner-推送与对外通道" aria-label="Permalink to &quot;3. ApplicationRunner：推送与对外通道&quot;">​</a></h2><h3 id="_3-1-sendmessage-先执行" tabindex="-1">3.1 <code>SendMessage</code>（先执行） <a class="header-anchor" href="#_3-1-sendmessage-先执行" aria-label="Permalink to &quot;3.1 `SendMessage`（先执行）&quot;">​</a></h3><p>启动定时推送：</p><ul><li>高频：按订阅向客户端推 depth / ticker / trade / kline；</li><li>低频：首页 ticker、排行榜。</li></ul><p>此时 Netty 可能尚未 bind，无连接时任务空转，属正常现象。</p><h3 id="_3-2-marketapplication-→-startexecuteutil-invoke" tabindex="-1">3.2 <code>MarketApplication</code> → <code>StartExecuteUtil.invoke()</code> <a class="header-anchor" href="#_3-2-marketapplication-→-startexecuteutil-invoke" aria-label="Permalink to &quot;3.2 `MarketApplication` → `StartExecuteUtil.invoke()`&quot;">​</a></h3><p>同一调用链内顺序：</p><ol><li><p><strong><code>putJobIsStart()</code></strong><br> 打开本机 Job 开关。之后外部触发的创建 K 线、刷新开盘价、核对交易对等才会真正 <code>asyncFireEvent</code>。</p></li><li><p><strong>第三方行情定时同步</strong>（延迟后周期执行）<br> 对非自有平台对接的交易对拉 depth / trade。依赖前面已写入的交易对列表；列表仍空时前几轮可能无操作。</p></li><li><p><strong>异步启动 Netty</strong><br><code>MarketServer.start()</code> bind 配置端口；与后续步骤并发，不阻塞等 bind 结束。</p></li><li><p><strong><code>setCoinType()</code></strong><br> Dubbo 拉币种、商户币种、交易对元数据进 <code>CoinPriceCache</code>，供展示名与折算。与 K 线主加载相互独立。</p></li><li><p><strong>其它定时任务</strong><br> 商户币种折合人民币、定期刷新币种缓存、人气榜等。</p></li></ol><h2 id="_4-交易对加载与推送的关系" tabindex="-1">4. 交易对加载与推送的关系 <a class="header-anchor" href="#_4-交易对加载与推送的关系" aria-label="Permalink to &quot;4. 交易对加载与推送的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数据</th><th>主要来源</th><th>作用</th></tr></thead><tbody><tr><td>交易对列表</td><td>Redis / 备份表 / <code>TradeTypeService</code></td><td>后续一切行情的主键集合</td></tr><tr><td>深度</td><td>Redis 或冷启动调 entrust；运行中还有 MQ</td><td>盘口</td></tr><tr><td>成交 / K 线 / Ticker</td><td>Redis protobuf、备份或 DB period</td><td>曲线与最新价</td></tr><tr><td>推送触发标记</td><td>加载末尾写入</td><td><code>SendMessage</code> 决定推什么</td></tr></tbody></table><p>运行期 MQ（如深度、成交消息）可能在 PostConstruct 尚未完全结束时到达，依赖写缓存逻辑的幂等与覆盖策略。</p><h2 id="_5-就绪分层" tabindex="-1">5. 就绪分层 <a class="header-anchor" href="#_5-就绪分层" aria-label="Permalink to &quot;5. 就绪分层&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>判断</th><th>能做什么</th></tr></thead><tbody><tr><td>框架 Ready</td><td>ApplicationReady</td><td>Dubbo / Jetty / MQ Consumer 起来</td></tr><tr><td>热路径行情就绪</td><td>PostConstruct 加载完成</td><td>RPC 读内存行情基本可用</td></tr><tr><td>WS 可连</td><td>Netty 启动成功日志</td><td>客户端可订阅</td></tr><tr><td>Job 可驱动</td><td><code>JOB_IS_START</code></td><td>分布式任务会在本机执行</td></tr><tr><td>冷启动未齐</td><td>部分 <code>initTradeData</code> 仍在跑</td><td>部分交易对深度 / K 线暂时为空</td></tr></tbody></table><p>运维心跳通常只检查 Redis 交易对列表是否可读，<strong>不检查 Netty</strong>。</p><h2 id="_6-依赖" tabindex="-1">6. 依赖 <a class="header-anchor" href="#_6-依赖" aria-label="Permalink to &quot;6. 依赖&quot;">​</a></h2><p>启动期常依赖：交易对服务、商户交易对、entrust 盘口（冷启动）、币种服务、第三方行情、报表人气等。<br> 撮合侧见<a href="/pages/070503">撮合初始化链路</a>；盘口业务语义见<a href="/pages/0706">行情与推送</a>。</p>',30))])}const _=o(c,[["render",s]]);export{m as __pageData,_ as default};
